use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () > { let lmdfb_data = fs :: read_to_string ("lmdfb_lattice_mapping.json") ? ; let lmdfb : serde_json :: Value = serde_json :: from_str (& lmdfb_data) ? ; let mut ontology = OwlOntology { classes : HashSet :: new () , properties : HashSet :: new () , individuals : HashSet :: new () , triples : Vec :: new () , domains : HashMap :: new () , ranges : HashMap :: new () , } ; ontology . classes . insert ("LatticeNode" . to_string ()) ; ontology . classes . insert ("Integer" . to_string ()) ; ontology . classes . insert ("Symbol" . to_string ()) ; ontology . classes . insert ("Layer" . to_string ()) ; ontology . classes . insert ("Crate" . to_string ()) ; ontology . classes . insert ("Declaration" . to_string ()) ; ontology . classes . insert ("FoundationLayer" . to_string ()) ; ontology . classes . insert ("SystemLayer" . to_string ()) ; ontology . classes . insert ("CompilerLayer" . to_string ()) ; ontology . classes . insert ("PowerOfTwo" . to_string ()) ; ontology . classes . insert ("SmallInteger" . to_string ()) ; ontology . classes . insert ("ErrorCode" . to_string ()) ; ontology . classes . insert ("CryptoConstant" . to_string ()) ; let properties = [("hasLevel" , "LatticeNode" , "Integer") , ("hasWeight" , "LatticeNode" , "Integer") , ("hasComplexity" , "LatticeNode" , "Integer") , ("hasSymbol" , "LatticeNode" , "Symbol") , ("belongsToLayer" , "LatticeNode" , "Layer") , ("belongsToCrate" , "LatticeNode" , "Crate") , ("hasEmoji" , "LatticeNode" , "Symbol") , ("dependsOn" , "LatticeNode" , "LatticeNode") , ("usesInteger" , "Declaration" , "Integer") , ("hasValue" , "Integer" , "Integer") , ("isTypeOf" , "Integer" , "Integer") ,] ; for (prop , domain , range) in properties { ontology . properties . insert (prop . to_string ()) ; ontology . domains . insert (prop . to_string () , domain . to_string ()) ; ontology . ranges . insert (prop . to_string () , range . to_string ()) ; } if let Some (nodes) = lmdfb ["nodes"] . as_object () { for (symbol , node) in nodes { let node_id = format ! ("node_{}" , sanitize_id (symbol)) ; ontology . individuals . insert (node_id . clone ()) ; ontology . triples . push ((node_id . clone () , "rdf:type" . to_string () , "LatticeNode" . to_string ())) ; ontology . triples . push ((node_id . clone () , "hasSymbol" . to_string () , format ! ("\"{}\"" , symbol))) ; if let Some (level) = node . get ("level") . and_then (| v | v . as_u64 ()) { let level_id = format ! ("level_{}" , level) ; ontology . individuals . insert (level_id . clone ()) ; ontology . triples . push ((level_id . clone () , "rdf:type" . to_string () , "Integer" . to_string ())) ; ontology . triples . push ((level_id . clone () , "hasValue" . to_string () , level . to_string ())) ; ontology . triples . push ((node_id . clone () , "hasLevel" . to_string () , level_id)) ; } if let Some (weight) = node . get ("weight") . and_then (| v | v . as_f64 ()) { let weight_int = (weight * 100.0) as i32 ; let weight_id = format ! ("weight_{}" , weight_int) ; ontology . individuals . insert (weight_id . clone ()) ; ontology . triples . push ((weight_id . clone () , "rdf:type" . to_string () , "Integer" . to_string ())) ; ontology . triples . push ((weight_id . clone () , "hasValue" . to_string () , weight_int . to_string ())) ; ontology . triples . push ((node_id . clone () , "hasWeight" . to_string () , weight_id)) ; } if let Some (layer) = node . get ("layer") . and_then (| v | v . as_str ()) { let layer_id = format ! ("layer_{}" , layer) ; ontology . individuals . insert (layer_id . clone ()) ; let layer_class = match layer { "foundation" => "FoundationLayer" , "system" => "SystemLayer" , "compiler" => "CompilerLayer" , _ => "Layer" } ; ontology . triples . push ((layer_id . clone () , "rdf:type" . to_string () , layer_class . to_string ())) ; ontology . triples . push ((node_id . clone () , "belongsToLayer" . to_string () , layer_id)) ; } if let Some (emoji) = node . get ("emoji") . and_then (| v | v . as_str ()) { ontology . triples . push ((node_id . clone () , "hasEmoji" . to_string () , format ! ("\"{}\"" , emoji))) ; } if let Some (crate_name) = symbol . split ("::") . next () { let crate_id = format ! ("crate_{}" , sanitize_id (crate_name)) ; ontology . individuals . insert (crate_id . clone ()) ; ontology . triples . push ((crate_id . clone () , "rdf:type" . to_string () , "Crate" . to_string ())) ; ontology . triples . push ((node_id . clone () , "belongsToCrate" . to_string () , crate_id)) ; } let integers = extract_integers_from_symbol (symbol) ; for integer in integers { let int_id = format ! ("int_{}" , integer) ; ontology . individuals . insert (int_id . clone ()) ; let int_type = classify_integer_type (integer) ; ontology . triples . push ((int_id . clone () , "rdf:type" . to_string () , int_type)) ; ontology . triples . push ((int_id . clone () , "hasValue" . to_string () , integer . to_string ())) ; ontology . triples . push ((node_id . clone () , "usesInteger" . to_string () , int_id)) ; } } } generate_owl_output (& ontology) ? ; println ! ("🦉 OWL Ontology Generated:") ; println ! ("   Classes: {}" , ontology . classes . len ()) ; println ! ("   Properties: {}" , ontology . properties . len ()) ; println ! ("   Individuals: {}" , ontology . individuals . len ()) ; println ! ("   Triples: {}" , ontology . triples . len ()) ; println ! ("   Saved to: lmdfb_ontology.owl") ; Ok (()) }